const tabId = 1962625065;
const mapDetails = await browserjs(tabId, () => {
  // Let's find maplibre instances or global variables
  let found = [];
  for (let k in window) {
    try {
      if (window[k] && typeof window[k] === 'object') {
        if (window[k]._canvas || window[k]._layers || window[k]._container) {
          found.push({ key: k, type: 'maplibre/mapbox' });
        }
      }
    } catch(e) {}
  }
  // Check window.mapContainers
  const containers = window.mapContainers;
  // Also check if canvas has content or WebGL context
  const canvas = document.querySelector('canvas');
  let glStatus = null;
  if (canvas) {
    const gl = canvas.getContext('webgl') || canvas.getContext('webgl2');
    glStatus = gl ? 'webgl-active' : 'no-gl';
  }
  return { found, containers, glStatus };
});
console.log("Map Details:", JSON.stringify(mapDetails, null, 2));

