  const subnavItems = Array.from(document.querySelectorAll('.subnav-item')).map(a => ({
    text: a.textContent.trim(),
    href: a.href,
    active: a.classList.contains('active')
  }));
  const headerCity = document.querySelector('.header-city-link')?.textContent.trim();
