  const legend = document.querySelector('.legend, .map-tools, .map-legend')?.textContent.trim();
  return {
    title: document.title,
    headerCity,
    breadcrumbs,
    activeSubnav,
    subnavItems,
    mapTitle,
    legend
  };
});
console.log(JSON.stringify(info, null, 2));

